import React, { useState } from 'react';
import { OrganizationChart } from 'primereact/organizationchart';

export default function Template() {
    const [data] = useState([
        {
            label: 'Argentina',
            expanded: true,
            data: 'ar',
            children: [
                {
                    label: 'Argentina',
                    expanded: true,
                    data: 'ar',
                    children: [
                        {
                            label: 'Argentina',
                            data: 'ar'
                        },
                        {
                            label: 'Croatia',
                            data: 'hr'
                        }
                    ]
                },
                {
                    label: 'France',
                    expanded: true,
                    data: 'fr',
                    children: [
                        {
                            label: 'France',
                            data: 'fr'
                        },
                        {
                            label: 'Morocco',
                            data: 'ma'
                        }
                    ]
                }
            ]
        }
    ]);

    const nodeTemplate = (node) => {
        return (
            <div className="fxb fcol fvc">
                <img alt={node.label} src="https://primefaces.org/cdn/primereact/images/flag/flag_placeholder.png" className={`w24px shadow-md flag flag-${node.data}`} />
                <div className="mgt3 font-size14">{node.label}</div>
            </div>
        );
    };

    return (
        <OrganizationChart value={data} nodeTemplate={nodeTemplate} />
    )

}